import sys
from typing import List, Set, Tuple, Optional

def solution(input_str: str):
    # Parse input
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        parts = lines[i].split()
        u, v = int(parts[0]), int(parts[1])
        adj[u].append(v)
        adj[v].append(u)

    # Calculate threshold
    k = int((n ** 0.5) + 0.5)

    # Try to find a cycle of length >= k
    visited = [False] * (n + 1)
    depth = [0] * (n + 1)  # depth in DFS tree
    parent = [0] * (n + 1)  # parent in DFS tree
    result_cycle = None

    def dfs_find_cycle(node, p, d):
        nonlocal result_cycle
        visited[node] = True
        depth[node] = d

        for neighbor in adj[node]:
            if neighbor == p:
                continue
            if visited[neighbor]:
                # Back edge found - cycle detected
                ancestor_depth = depth[neighbor]
                if ancestor_depth > 0:  # not parent
                    cycle_len = d - ancestor_depth + 1
                    if cycle_len >= k:
                        # Extract cycle by following parent pointers
                        cycle = []
                        cur = node
                        while cur != neighbor:
                            cycle.append(cur)
                            cur = parent[cur]
                        cycle.append(neighbor)
                        result_cycle = cycle
                        return
            else:
                parent[neighbor] = node
                if result_cycle:
                    return
                dfs_find_cycle(neighbor, node, d + 1)

    # DFS from all nodes to find longest cycle
    for i in range(1, n + 1):
        if not visited[i]:
            dfs_find_cycle(i, 0, 0)
            if result_cycle:
                break

    if result_cycle:
        # Output cycle
        output = "2"
        output += f"\n{len(result_cycle)}"
        output += f"\n{' '.join(map(str, result_cycle))}"
        print(output)
        return

    # Fall back to finding independent set of size >= k
    indep = []
    used = [False] * (n + 1)
    component_nodes = []

    # Find large independent set using greedy approach on components
    for i in range(1, n + 1):
        if used[i]:
            continue

        # BFS to find connected component
        queue = [i]
        used[i] = True
        comp = [i]

        idx = 0
        while idx < len(queue):
            node = queue[idx]
            idx += 1
            for neighbor in adj[node]:
                if not used[neighbor]:
                    used[neighbor] = True
                    comp.append(neighbor)
                    queue.append(neighbor)

        # Greedily select independent set from component
        sel = []
        for node in comp:
            connected = False
            for s in sel:
                if node in adj[s]:
                    connected = True
                    break
            if not connected:
                sel.append(node)

        # If component alone isn't enough, try more nodes
        for i in range(1, n + 1):
            if i in comp:
                continue
            if i in used:
                continue
            connected = False
            for s in sel:
                if i in adj[s] or s in adj[i]:
                    connected = True
                    break
            if not connected:
                sel.append(i)

    # Ensure size is at least k
    if len(sel) < k:
        for i in range(1, n + 1):
            if len(sel) >= k:
                break
            if not used[i]:
                connected = False
                for s in sel:
                    if i in adj[s]:
                        connected = True
                        break
                if not connected:
                    sel.append(i)

    # Output independent set
    output = "1"
    output += f"\n{len(sel)}"
    output += f"\n{' '.join(map(str, sel))}"
    print(output)

