# Solution to the bipartite graph k-covering problem
def solution(data):
    lines = data.strip().split('\n')
    n1, n2, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u, v))

    # Calculate degrees and find minDegree
    deg = [0] * (n1 + n2 + 1)
    for u, v in edges:
        deg[u] += 1
        deg[n1 + v] += 1

    min_deg = 0
