def solution(input_string):
    """
    Solve the cake stacking problem.
    Returns a string representation of the maximum volume.
    """
    import math

    lines = input_string.strip().split('\n')
    n = int(lines[0])

    if n == 0:
        return '0.000000000'

    # Calculate volumes for each cake
    volumes = []
    idx = 1
    for i in range(n):
        r, h = map(int, lines[idx].split())
        idx += 1
        volume = math.pi * r * r * h
        volumes.append(volume)

    # Coordinate compression for volumes
    unique_volumes = sorted(set(volumes))
    vol_map = {v: i + 1 for i, v in enumerate(unique_volumes)}
    m = len(unique_volumes)

    # Binary Indexed Tree for maximum query
    tree = [0.0] * (m + 1)

    def update(i, val):
        """Update tree at position i with value val (max operation)"""
        while i <= m:
            tree[i] = max(tree[i], val)
            i += i & (-i)

    def query(i):
        """Query maximum value in range [1, i]"""
        result = 0.0
        while i > 0:
            result = max(result, tree[i])
            i -= i & (-i)
        return result

    # DP: dp[i] = max volume sum ending at cake i
    # For each cake, find max sum from all previous cakes with smaller volume
    max_total = 0.0

    for v in volumes:
        cid = vol_map[v]
        prev_max = query(cid - 1)  # Max volume sum for cakes with smaller volume
        current_total = prev_max + v
        update(cid, current_total)
        max_total = max(max_total, current_total)

    return f"{max_total:.9f}"

