    return res

def power(a, b, mod):
    res = [[0] * len(a) for _ in range(len(a))]
    for i in range(len(a)):
        res[i][i] = 1
    while b > 0:
        if b % 2 == 1:
            res = multiply(res, a, mod)
        a = multiply(a, a, mod)
        b //= 2
    return res

