                break

            if l <= a - b <= r:
                # Ballot theorem: (a-b+1)/(a+1) * C(a+b, a)
                if a + b == 0:
                    ballot = 0  # More efficient for edge case
                else:
                    ballot = (a - b + 1) * nCr(a + b, a) % MOD
                    ballot = ballot * inv[a + 1] % MOD
                ways_C = nCr(n, c)
                total = (total + ballot * ways_C) % MOD

